class Solution:
    def finalPrices(self, prices: List[int]) -> List[int]:
        ans = prices[:]
        stack = []                              # 还没找到折扣的下标，价格从栈底到栈顶递增
        for i, p in enumerate(prices):
            while stack and prices[stack[-1]] >= p:     # p 是它右边第一个不超过它的价格
                ans[stack.pop()] -= p
            stack.append(i)
        return ans

