class Solution {
    public int[] finalPrices(int[] prices) {
        int[] ans = prices.clone();
        Deque<Integer> stack = new ArrayDeque<>();      // 还没找到折扣的下标，价格从栈底到栈顶递增
        for (int i = 0; i < prices.length; i++) {
            while (!stack.isEmpty() && prices[stack.peek()] >= prices[i]) { // prices[i] 是它右边第一个不超过它的价格
                ans[stack.pop()] -= prices[i];
            }
            stack.push(i);
        }
        return ans;
    }
}

