public:
    vector<int> finalPrices(vector<int>& prices) {
        vector<int> ans = prices;
        vector<int> st;                                 // 还没找到折扣的下标，价格从栈底到栈顶递增
        for (int i = 0; i < (int)prices.size(); i++) {
            while (!st.empty() && prices[st.back()] >= prices[i]) { // prices[i] 是它右边第一个不超过它的价格
                ans[st.back()] -= prices[i];
                st.pop_back();
            }
            st.push_back(i);
        }
        return ans;
    }
};

