class Solution {
    public int[] minSlidingWindow(int[] nums, int k) {
        Deque<Integer> q = new ArrayDeque<>();          // 存下标，对应的值从队头到队尾递增
        int[] res = new int[nums.length - k + 1];
        for (int i = 0; i < nums.length; i++) {
            while (!q.isEmpty() && nums[q.peekLast()] >= nums[i]) {     // 比 nums[i] 大的以后不可能是最小值了
                q.pollLast();
            }
            q.offerLast(i);
            if (q.peekFirst() <= i - k) {               // 队头滑出了窗口
                q.pollFirst();
            }
            if (i >= k - 1) {                           // 窗口满了：队头就是最小值
                res[i - k + 1] = nums[q.peekFirst()];
            }
        }
        return res;
    }
}

